const btn=(label,action,secondary=false)=>`<button class="btn${secondary?' secondary':''}" data-action="${action}">${label}<span class="arrow" aria-hidden="true">↗</span></button>`;
const link=(label,path,secondary=false)=>`<a class="btn${secondary?' secondary':''}" href="#demo/${path}">${label}<span class="arrow" aria-hidden="true">↗</span></a>`;
function toast(text){const el=document.querySelector('#toast');el.textContent=typeof tr==='function'?tr(text):text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,3800);}
function download(name,text,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
